-- Hyprland config (Lua, Hyprland 0.56+)
-- Wiki: https://wiki.hypr.land/Configuring/Start/
--
-- require() paths are relative to this file: require("binds") loads ./binds.lua.
-- Hyprland may not watch required files for changes; run `hyprctl reload` after editing one.

require("monitors")
require("env")
require("autostart")
require("look")
require("input")
require("binds")
require("rules")
require("windows")

-- colors.lua is generated by matugen (see ~/.config/matugen/config.toml) and isn't in git.
-- Loaded last so it overrides the fallback border colors in look.lua.
-- pcall: a missing required file would otherwise abort the rest of this file.
local ok, err = pcall(require, "colors")
if not ok then
    print("hyprland.lua: colors.lua not loaded, using fallback colors (" .. tostring(err) .. ")")
end

-- shell-settings.lua is written by Quickshell's settings window (keyboard, touchpad, gaps,
-- borders, corners) and isn't in git. Last, so it overrides input.lua and look.lua.
ok, err = pcall(require, "shell-settings")
if not ok then
    print("hyprland.lua: shell-settings.lua not loaded, using input.lua and look.lua (" .. tostring(err) .. ")")
end
